public class FitnessFunction_decode_TriageGen0Test {

    /**
     * Helper method to set the private field 'boundaries' using reflection
     * since it is not exposed via the constructor in the provided snippet.
     */
    private void setBoundaries(CMAESOptimizer.FitnessFunction fitnessFunction, double[][] boundaries) throws Exception {
        Field field = CMAESOptimizer.FitnessFunction.class.getDeclaredField("boundaries");
        field.setAccessible(true);
        field.set(fitnessFunction, boundaries);
    }

    @Test
    public void testDecode_BoundariesIsNull() {
        CMAESOptimizer.FitnessFunction fitnessFunction = new CMAESOptimizer.FitnessFunction();
        // boundaries is null by default if not set
        double[] x = {1.0, 2.0, 3.0};
        double[] result = fitnessFunction.decode(x);

        // When boundaries is null, it should return the input array x directly
        Assert.assertArrayEquals(x, result, 1e-9);
        Assert.assertSame(x, result);
    }

    @Test
    public void testDecode_NormalOperation() throws Exception {
        CMAESOptimizer.FitnessFunction fitnessFunction = new CMAESOptimizer.FitnessFunction();

        // boundaries[0] is lower bound, boundaries[1] is upper bound
        double[][] boundaries = {
            {0.0, 10.0, -5.0}, // Lower bounds
            {1.0, 20.0,  5.0}  // Upper bounds
        };
        setBoundaries(fitnessFunction, boundaries);

        // x represents values in range [0, 1]
        double[] x = {0.0, 0.5, 1.0};

        // Calculations:
        // i=0: diff = 1.0 - 0.0 = 1.0; res = 1.0 * 0.0 + 0.0 = 0.0
        // i=1: diff = 20.0 - 10.0 = 10.0; res = 10.0 * 0.5 + 10.0 = 15.0
        // i=2: diff = 5.0 - (-5.0) = 10.0; res = 10.0 * 1.0 + (-5.0) = 5.0
        double[] expected = {0.0, 15.0, 5.0};

        double[] result = fitnessFunction.decode(x);

        Assert.assertArrayEquals(expected, result, 1e-9);
        // Ensure it's a new array and not the same instance
        Assert.assertNotSame(x, result);
    }

    @Test
    public void testDecode_NegativeBoundariesAndZeroDiff() throws Exception {
        CMAESOptimizer.FitnessFunction fitnessFunction = new CMAESOptimizer.FitnessFunction();

        double[][] boundaries = {
            {-10.0, 5.0},
            {-10.0, 15.0}
        };
        setBoundaries(fitnessFunction, boundaries);

        double[] x = {0.5, 0.2};

        // i=0: diff = -10.0 - (-10.0) = 0.0; res = 0.0 * 0.5 + (-10.0) = -10.0
        // i=1: diff = 15.0 - 5.0 = 10.0; res = 10.0 * 0.2 + 5.0 = 7.0
        double[] expected = {-10.0, 7.0};

        double[] result = fitnessFunction.decode(x);

        Assert.assertArrayEquals(expected, result, 1e-9);
    }

    @Test
    public void testDecode_EmptyArray() throws Exception {
        CMAESOptimizer.FitnessFunction fitnessFunction = new CMAESOptimizer.FitnessFunction();

        double[][] boundaries = {
            {},
            {}
        };
        setBoundaries(fitnessFunction, boundaries);

        double[] x = {};
        double[] result = fitnessFunction.decode(x);

        Assert.assertEquals(0, result.length);
    }
}
